# SPDX-License-Identifier: MIT-0
import Base
import ./main.bend as M
import ./LAWS.bend as L

def L.path_empty(V,path):
  match path:
    case Nil{}: {==}
    case Con{False{},+tail}: L.path_empty(V,tail)
    case Con{True{},+tail}: L.path_empty(V,tail)

def L.path_set(V,path,m,key,v):
  match path:
    case Nil{}: {==}
    case Con{False{},+tail}: L.path_set(V,tail,M.low(V,m),key,v)
    case Con{True{},+tail}: L.path_set(V,tail,M.high(V,m),key,v)

def L.branch_low(V,lo,hi):
  match lo:
    case M.Tip{}:
      match hi:
        case M.Tip{}: {==}
        case M.Entry{k,v}: {==}
        case M.Branch{a,b}: {==}
    case M.Entry{k,v}: {==}
    case M.Branch{a,b}: {==}

def L.branch_high(V,lo,hi):
  match lo:
    case M.Tip{}:
      match hi:
        case M.Tip{}: {==}
        case M.Entry{k,v}: {==}
        case M.Branch{a,b}: {==}
    case M.Entry{k,v}: {==}
    case M.Branch{a,b}: {==}

def L.path_remove(V,path,m):
  match path:
    case Nil{}: {==}
    case Con{False{},+tail}:
      %Equal.sym(M.IntMap<V>,M.low(V,M.branch(V,M.remove_path(V,tail,M.low(V,m)),M.high(V,m))),M.remove_path(V,tail,M.low(V,m)),L.branch_low(V,M.remove_path(V,tail,M.low(V,m)),M.high(V,m))) : {M.get_path(V,tail,_) == None{} : Maybe<&2,V>}
      L.path_remove(V,tail,M.low(V,m))
    case Con{True{},+tail}:
      %Equal.sym(M.IntMap<V>,M.high(V,M.branch(V,M.low(V,m),M.remove_path(V,tail,M.high(V,m)))),M.remove_path(V,tail,M.high(V,m)),L.branch_high(V,M.low(V,m),M.remove_path(V,tail,M.high(V,m)))) : {M.get_path(V,tail,_) == None{} : Maybe<&2,V>}
      L.path_remove(V,tail,M.high(V,m))

def L.empty_get(V,key): L.path_empty(V,M.bits(32n,key))
def L.set_get(V,m,key,v): L.path_set(V,M.bits(32n,key),m,key,v)
def L.remove_get(V,m,key): L.path_remove(V,M.bits(32n,key),m)

def L.set_contains(V,m,key,v):
  %Equal.sym(Maybe<&2,V>,M.IntMap.get(V,M.IntMap.set(V,m,key,v),key),Some{v},L.set_get(V,m,key,v)) : {M.present(V,_) == True{} : Bool}
  {==}

def L.overwrite(V,m,key,old,v):
  L.set_get(V,M.IntMap.set(V,m,key,old),key,v)

def L.path_preserve(V,p,q,m,key,v,distinct):
  match p:
    case Nil{}:
      match distinct:
    case Con{False{},pt}:
      match q:
        case Nil{}:
          match distinct:
        case Con{False{},qt}: L.path_preserve(V,pt,qt,M.low(V,m),key,v,distinct)
        case Con{True{},qt}: {==}
    case Con{True{},pt}:
      match q:
        case Nil{}:
          match distinct:
        case Con{False{},qt}: {==}
        case Con{True{},qt}: L.path_preserve(V,pt,qt,M.high(V,m),key,v,distinct)

def L.set_preserves(V,m,key,other,v,distinct):
  L.path_preserve(V,M.bits(32n,key),M.bits(32n,other),m,key,v,distinct)

def L.distinct_witness(): Unit{}

def L.boundary_fixture(): {==}

def L.fold_fixture(): {==}

def L.union_fixture(): {==}

def L.invocation_fixture(): {==}

def L.model_union_fixture(): {==}

def L.observe_low(V,path,lo,hi):
  Equal.cong(M.IntMap<V>,Maybe<&2,V>,x => M.get_path(V,path,x),M.low(V,M.branch(V,lo,hi)),lo,L.branch_low(V,lo,hi))

def L.observe_high(V,path,lo,hi):
  Equal.cong(M.IntMap<V>,Maybe<&2,V>,x => M.get_path(V,path,x),M.high(V,M.branch(V,lo,hi)),hi,L.branch_high(V,lo,hi))

def L.path_remove_preserve(V,p,q,m,distinct):
  match p:
    case Nil{}:
      match distinct:
    case Con{False{},+pt}:
      match q:
        case Nil{}:
          match distinct:
        case Con{False{},+qt}:
          Equal.trans(Maybe<&2,V>,
            M.get_path(V,qt,M.low(V,M.branch(V,M.remove_path(V,pt,M.low(V,m)),M.high(V,m)))),
            M.get_path(V,qt,M.remove_path(V,pt,M.low(V,m))),M.get_path(V,qt,M.low(V,m)),
            L.observe_low(V,qt,M.remove_path(V,pt,M.low(V,m)),M.high(V,m)),
            L.path_remove_preserve(V,pt,qt,M.low(V,m),distinct))
        case Con{True{},qt}:
          L.observe_high(V,qt,M.remove_path(V,pt,M.low(V,m)),M.high(V,m))
    case Con{True{},+pt}:
      match q:
        case Nil{}:
          match distinct:
        case Con{False{},qt}:
          L.observe_low(V,qt,M.low(V,m),M.remove_path(V,pt,M.high(V,m)))
        case Con{True{},+qt}:
          Equal.trans(Maybe<&2,V>,
            M.get_path(V,qt,M.high(V,M.branch(V,M.low(V,m),M.remove_path(V,pt,M.high(V,m))))),
            M.get_path(V,qt,M.remove_path(V,pt,M.high(V,m))),M.get_path(V,qt,M.high(V,m)),
            L.observe_high(V,qt,M.low(V,m),M.remove_path(V,pt,M.high(V,m))),
            L.path_remove_preserve(V,pt,qt,M.high(V,m),distinct))

def L.remove_preserves(V,m,key,other,distinct):
  L.path_remove_preserve(V,M.bits(32n,key),M.bits(32n,other),m,distinct)

def L.fold_seed_fixture(): {==}

# SPDX-License-Identifier: MIT-0
import Base
import ./main.bend as M
import ./model.bend as Ref

def maybe_eq(a: Maybe<&2,U32>, b: Maybe<&2,U32>) -> Bool:
  match a:
    case None{}:
      match b:
        case None{}: True{}
        case Some{x}: False{}
    case Some{x}:
      match b:
        case None{}: False{}
        case Some{y}: U32.is_eq(x,y)

def items_eq(a: List<&2,Ref.Item<U32>>, b: List<&2,Ref.Item<U32>>) -> Bool:
  match a:
    case Nil{}:
      match b:
        case Nil{}: True{}
        case Con{x,xs}: False{}
    case Con{Ref.Item{k,v},xs}:
      match b:
        case Nil{}: False{}
        case Con{Ref.Item{j,w},ys}: Bool.and(U32.is_eq(k,j),Bool.and(U32.is_eq(v,w),items_eq(xs,ys)))

def entries(m: M.IntMap<U32>) -> List<&2,Ref.Item<U32>>:
  List.reverse(&2,Ref.Item<U32>,M.IntMap.fold(~U32,~List<&2,Ref.Item<U32>>,~(acc => k => v => Con{Ref.Item{k,v},acc}),m,Nil{}))

def probes(xs: List<&2,Ref.Item<U32>>, +m: M.IntMap<U32>, +model: List<&2,Ref.Item<U32>>) -> Bool:
  match xs:
    case Nil{}: True{}
    case Con{Ref.Item{+k,v},tail}:
      Bool.and(maybe_eq(M.IntMap.get(U32,m,k),Ref.get(U32,model,k)),probes(tail,m,model))

def agree(+m: M.IntMap<U32>, +model: List<&2,Ref.Item<U32>>) -> Bool:
  Bool.and(Nat.is_eq(M.IntMap.size(U32,m),Ref.size(U32,model)),
    Bool.and(probes(model,m,model),Bool.and(probes(entries(m),m,model),
      Nat.is_eq(Ref.size(U32,entries(m)),Ref.size(U32,model)))))

def boundary() -> Bool:
  +a = M.IntMap.set(U32,M.IntMap.empty(U32),0,0)
  +b = M.IntMap.set(U32,a,4294967295,99)
  +c = M.IntMap.set(U32,b,0,17)
  +d = M.IntMap.remove(U32,c,4294967295)
  +e = M.IntMap.remove(U32,d,0)
  Bool.and(maybe_eq(M.IntMap.get(U32,a,0),Some{0}),
  Bool.and(M.IntMap.contains(U32,a,0),
  Bool.and(Bool.not(M.IntMap.contains(U32,a,1)),
  Bool.and(agree(b,[Ref.Item{0,0},Ref.Item{4294967295,99}]),
  Bool.and(agree(c,[Ref.Item{0,17},Ref.Item{4294967295,99}]),
  Bool.and(agree(d,[Ref.Item{0,17}]),
  Bool.and(agree(e,Nil{}),agree(M.IntMap.remove(U32,b,2147483648),[Ref.Item{0,0},Ref.Item{4294967295,99}]))))))))

def bit_cases(n: Nat, +key: U32) -> Bool:
  match n:
    case 0n: True{}
    case 1n+p:
      +complement = U32.not(key)
      +m = M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.empty(U32),0,7),key,23),complement,41)
      Bool.and(agree(m,[Ref.Item{0,7},Ref.Item{key,23},Ref.Item{complement,41}]),
        Bool.and(agree(M.IntMap.remove(U32,m,key),[Ref.Item{0,7},Ref.Item{complement,41}]),bit_cases(p,U32.shl(key))))

def order_case() -> Bool:
  m = M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.empty(U32),1,11),2,22),0,0),2147483648,33)
  items_eq(entries(m),[Ref.Item{0,0},Ref.Item{2147483648,33},Ref.Item{2,22},Ref.Item{1,11}])

def noncomm(a: U32, b: U32) -> U32: U32.add(U32.mul(a,100),b)

def left() -> M.IntMap<U32>:
  M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.empty(U32),0,2),4294967295,3)

def right() -> M.IntMap<U32>:
  M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.empty(U32),1,5),4294967295,7)

def unions() -> Bool:
  +l = left()
  +r = right()
  Bool.and(agree(M.IntMap.union_with(~U32,~noncomm,l,r),[Ref.Item{0,2},Ref.Item{1,5},Ref.Item{4294967295,307}]),
  Bool.and(agree(M.IntMap.union_with(~U32,~U32.add,l,r),[Ref.Item{0,2},Ref.Item{1,5},Ref.Item{4294967295,10}]),
  Bool.and(agree(M.IntMap.union_with(~U32,~(a => b => U32.max(a,b)),l,r),[Ref.Item{0,2},Ref.Item{1,5},Ref.Item{4294967295,7}]),
  Bool.and(agree(M.IntMap.union_with(~U32,~noncomm,M.IntMap.empty(U32),r),[Ref.Item{1,5},Ref.Item{4294967295,7}]),
  Bool.and(agree(M.IntMap.union_with(~U32,~noncomm,l,M.IntMap.empty(U32)),[Ref.Item{0,2},Ref.Item{4294967295,3}]),
  Bool.and(agree(l,[Ref.Item{0,2},Ref.Item{4294967295,3}]),agree(r,[Ref.Item{1,5},Ref.Item{4294967295,7}])))))))

# A combiner result records its complete invocation tree, including order.
type Trace is Data:
  Atom{value: U32}
  Join{left: Trace, right: Trace}

def join(a: Trace, b: Trace) -> Trace: Join{a,b}

def trace_result(a: Maybe<&2,Trace>, b: Maybe<&2,Trace>, c: Maybe<&2,Trace>) -> Bool:
  match a:
    case None{}: False{}
    case Some{x}:
      match x:
        case Atom{v}: False{}
        case Join{Atom{l},Atom{r}}:
          match b:
            case None{}: False{}
            case Some{Atom{b}}:
              match c:
                case None{}: False{}
                case Some{Atom{c}}: Bool.and(U32.is_eq(l,2),Bool.and(U32.is_eq(r,7),Bool.and(U32.is_eq(b,11),U32.is_eq(c,13))))
                case Some{Join{x,y}}: False{}
            case Some{Join{x,y}}: False{}
        case Join{Atom{l},Join{a,b}}: False{}
        case Join{Join{a,b},r}: False{}

def trace_case() -> Bool:
  l = M.IntMap.set(Trace,M.IntMap.set(Trace,M.IntMap.empty(Trace),9,Atom{2}),10,Atom{11})
  r = M.IntMap.set(Trace,M.IntMap.set(Trace,M.IntMap.empty(Trace),9,Atom{7}),12,Atom{13})
  +m = M.IntMap.union_with(~Trace,~join,l,r)
  trace_result(M.IntMap.get(Trace,m,9),M.IntMap.get(Trace,m,10),M.IntMap.get(Trace,m,12))

def query_domain(n: Nat, +m: M.IntMap<U32>, +model: List<&2,Ref.Item<U32>>) -> Bool:
  match n:
    case 0n: True{}
    case 1n+ +p:
      +k = U32.from_nat(p)
      Bool.and(maybe_eq(M.IntMap.get(U32,m,k),Ref.get(U32,model,k)),
        Bool.and(Bool.not(Bool.xor(M.IntMap.contains(U32,m,k),M.present(U32,Ref.get(U32,model,k)))),query_domain(p,m,model)))

def sequence(n: Nat, +seed: U32, +m: M.IntMap<U32>, +model: List<&2,Ref.Item<U32>>) -> Bool:
  match n:
    case 0n: Bool.and(agree(m,model),query_domain(64n,m,model))
    case 1n+ +p:
      +key = U32.and(seed,63)
      +next = U32.add(U32.mul(seed,1664525),1013904223)
      +changed = M.IntMap.set(U32,m,key,seed)
      +expected = Ref.set(U32,model,key,seed)
      +removed = M.IntMap.remove(U32,changed,U32.and(U32.shr(seed),63))
      +removed_model = Ref.remove(U32,expected,U32.and(U32.shr(seed),63))
      Bool.and(query_domain(64n,changed,expected),Bool.and(query_domain(64n,removed,removed_model),Bool.and(agree(m,model),Bool.and(agree(changed,expected),Bool.and(agree(removed,removed_model),sequence(p,next,removed,removed_model))))))

def union_model() -> Bool:
  +l = {[Ref.Item{0,2},Ref.Item{4294967295,3}] : List<&2,Ref.Item<U32>>}
  +r = {[Ref.Item{1,5},Ref.Item{4294967295,7}] : List<&2,Ref.Item<U32>>}
  agree(M.IntMap.union_with(~U32,~noncomm,left(),right()),Ref.union_with(~U32,~noncomm,r,l))

def fill(n: Nat, +seed: U32, m: M.IntMap<U32>, xs: List<&2,Ref.Item<U32>>) -> M.IntMap<U32> & List<&2,Ref.Item<U32>>:
  match n:
    case 0n: (m,xs)
    case 1n+p:
      +key = U32.and(seed,127)
      fill(p,U32.add(U32.mul(seed,1664525),1013904223),M.IntMap.set(U32,m,key,seed),Ref.set(U32,xs,key,seed))

def union_stress_check(+a: M.IntMap<U32>, +x: List<&2,Ref.Item<U32>>, +b: M.IntMap<U32>, +y: List<&2,Ref.Item<U32>>) -> Bool:
  Bool.and(agree(M.IntMap.union_with(~U32,~noncomm,a,b),Ref.union_with(~U32,~noncomm,y,x)),
    Bool.and(agree(M.IntMap.union_with(~U32,~U32.add,a,b),Ref.union_with(~U32,~U32.add,y,x)),
      Bool.and(agree(M.IntMap.union_with(~U32,~(a => b => U32.max(a,b)),a,b),Ref.union_with(~U32,~(a => b => U32.max(a,b)),y,x)),
        Bool.and(agree(a,x),agree(b,y)))))

def union_stress_pairs(a: M.IntMap<U32> & List<&2,Ref.Item<U32>>, b: M.IntMap<U32> & List<&2,Ref.Item<U32>>) -> Bool:
  match a:
    case Tuple{am,ax}:
      match b:
        case Tuple{bm,bx}: union_stress_check(am,ax,bm,bx)

def union_stress() -> Bool:
  union_stress_pairs(fill(96n,731,M.IntMap.empty(U32),Nil{}),fill(96n,9923,M.IntMap.empty(U32),Nil{}))

def fold_seed_case() -> Bool:
  +m = M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.set(U32,M.IntMap.empty(U32),0,7),1,11),2,22)
  +seed = {[Ref.Item{99,123}] : List<&2,Ref.Item<U32>>}
  Bool.and(items_eq(M.IntMap.fold(~U32,~List<&2,Ref.Item<U32>>,~(acc => k => v => Con{Ref.Item{k,v},acc}),m,seed),
    [Ref.Item{1,11},Ref.Item{2,22},Ref.Item{0,7},Ref.Item{99,123}]),
    items_eq(M.IntMap.fold(~U32,~List<&2,Ref.Item<U32>>,~(acc => k => v => Con{Ref.Item{k,v},acc}),M.IntMap.empty(U32),seed),seed))

# SPDX-License-Identifier: MIT-0
import Base

# Internal constructors: public maps are built through the IntMap operations.
type IntMap<-V: Data> is Data:
  Tip{}
  Entry{key: U32, value: V}
  Branch{lo: IntMap<V>, hi: IntMap<V>}

def bits(n: Nat, +key: U32) -> List<&2,Bool>:
  match n:
    case 0n:
      Nil{}
    case 1n+p:
      Con{U32.is_ne(U32.and(key,1),0),bits(p,U32.shr(key))}

def low(-V: Data, m: IntMap<V>) -> IntMap<V>:
  match m:
    case Tip{}: Tip{}
    case Entry{k,v}: Tip{}
    case Branch{lo,hi}: lo

def high(-V: Data, m: IntMap<V>) -> IntMap<V>:
  match m:
    case Tip{}: Tip{}
    case Entry{k,v}: Tip{}
    case Branch{lo,hi}: hi

def value(-V: Data, m: IntMap<V>) -> Maybe<&2,V>:
  match m:
    case Tip{}: None{}
    case Entry{k,v}: Some{v}
    case Branch{lo,hi}: None{}

def get_path(-V: Data, path: List<&2,Bool>, m: IntMap<V>) -> Maybe<&2,V>:
  match path:
    case Nil{}:
      value(V,m)
    case Con{False{},tail}:
      get_path(V,tail,low(V,m))
    case Con{True{},tail}:
      get_path(V,tail,high(V,m))

def edit_path(~join: @-T: Data -> IntMap<T> -> IntMap<T> -> IntMap<T>,
              -V: Data, path: List<&2,Bool>, +m: IntMap<V>, end: IntMap<V>) -> IntMap<V>:
  match path:
    case Nil{}:
      end
    case Con{False{},tail}:
      join(V,edit_path(~join,V,tail,low(V,m),end),high(V,m))
    case Con{True{},tail}:
      join(V,low(V,m),edit_path(~join,V,tail,high(V,m),end))

def set_path(-V: Data, path: List<&2,Bool>, +m: IntMap<V>, key: U32, v: V) -> IntMap<V>:
  edit_path(~(T => lo => hi => Branch{lo,hi}),V,path,m,Entry{key,v})

def branch(-V: Data, lo: IntMap<V>, hi: IntMap<V>) -> IntMap<V>:
  match lo hi:
    case Tip{} Tip{}: Tip{}
    case a b: Branch{a,b}

def remove_path(-V: Data, path: List<&2,Bool>, +m: IntMap<V>) -> IntMap<V>:
  edit_path(~branch,V,path,m,Tip{})

def IntMap.empty(-V: Data) -> IntMap<V>:
  Tip{}

def IntMap.get(-V: Data, m: IntMap<V>, key: U32) -> Maybe<&2,V>:
  get_path(V,bits(32n,key),m)

def IntMap.set(-V: Data, m: IntMap<V>, +key: U32, v: V) -> IntMap<V>:
  set_path(V,bits(32n,key),m,key,v)

def IntMap.remove(-V: Data, m: IntMap<V>, key: U32) -> IntMap<V>:
  remove_path(V,bits(32n,key),m)

def present(-V: Data, v: Maybe<&2,V>) -> Bool:
  match v:
    case None{}: False{}
    case Some{x}: True{}

def IntMap.contains(-V: Data, m: IntMap<V>, key: U32) -> Bool:
  present(V,IntMap.get(V,m,key))

def IntMap.size(-V: Data, m: IntMap<V>) -> Nat:
  match m:
    case Tip{}: 0n
    case Entry{k,v}: 1n
    case Branch{lo,hi}: Nat.add(IntMap.size(V,lo),IntMap.size(V,hi))

def IntMap.fold(~V: Data, ~A: Type, ~step: A -> U32 -> V -> A, m: IntMap<V>, acc: A) -> A:
  match m:
    case Tip{}: acc
    case Entry{k,v}: step(acc,k,v)
    case Branch{lo,hi}:
      IntMap.fold(~V,~A,~step,hi,IntMap.fold(~V,~A,~step,lo,acc))

def combine_value(~V: Data, ~combine: V -> V -> V, old: Maybe<&2,V>, right: V) -> V:
  match old:
    case None{}: right
    case Some{left}: combine(left,right)

def union_step(~V: Data, ~combine: V -> V -> V, +left: IntMap<V>, +key: U32, right: V) -> IntMap<V>:
  IntMap.set(V,left,key,combine_value(~V,~combine,IntMap.get(V,left,key),right))

def IntMap.union_with(~V: Data, ~combine: V -> V -> V, left: IntMap<V>, right: IntMap<V>) -> IntMap<V>:
  IntMap.fold(~V,~IntMap<V>,~(acc => key => v => union_step(~V,~combine,acc,key,v)),right,left)

# SPDX-License-Identifier: MIT-0
import Base

# Independent association list: no trie, key bits, or implementation import.
type Item<-V: Data> is Data:
  Item{key: U32, value: V}

def choose(-V: Data, same: Bool, v: V, rest: Maybe<&2,V>) -> Maybe<&2,V>:
  match same:
    case False{}: rest
    case True{}: Some{v}

def get(-V: Data, xs: List<&2,Item<V>>, +key: U32) -> Maybe<&2,V>:
  match xs:
    case Nil{}: None{}
    case Con{Item{k,v},tail}: choose(V,U32.is_eq(k,key),v,get(V,tail,key))

def keep(-V: Data, same: Bool, x: Item<V>, tail: List<&2,Item<V>>) -> List<&2,Item<V>>:
  match same:
    case False{}: Con{x,tail}
    case True{}: tail

def remove(-V: Data, xs: List<&2,Item<V>>, +key: U32) -> List<&2,Item<V>>:
  match xs:
    case Nil{}: Nil{}
    case Con{Item{+k,v},tail}: keep(V,U32.is_eq(k,key),Item{k,v},remove(V,tail,key))

def set(-V: Data, xs: List<&2,Item<V>>, +key: U32, v: V) -> List<&2,Item<V>>:
  Con{Item{key,v},remove(V,xs,key)}

def size(-V: Data, xs: List<&2,Item<V>>) -> Nat:
  match xs:
    case Nil{}: 0n
    case Con{x,tail}: 1n+size(V,tail)

def merged(~V: Data, ~f: V -> V -> V, old: Maybe<&2,V>, v: V) -> V:
  match old:
    case None{}: v
    case Some{x}: f(x,v)

def union_with(~V: Data, ~f: V -> V -> V, right: List<&2,Item<V>>, +left: List<&2,Item<V>>) -> List<&2,Item<V>>:
  match right:
    case Nil{}: left
    case Con{Item{+k,v},tail}:
      union_with(~V,~f,tail,set(V,left,k,merged(~V,~f,get(V,left,k),v)))
